struct ServerEnvelopeBuilder {
  typedef ServerEnvelope Table;
  ::flatbuffers::FlatBufferBuilder &fbb_;
  ::flatbuffers::uoffset_t start_;
  void add_msg_type(cyberpunk_rp::protocol::ServerMsg msg_type) {
    fbb_.AddElement<uint8_t>(ServerEnvelope::VT_MSG_TYPE, static_cast<uint8_t>(msg_type), 0);
  }
  void add_msg(::flatbuffers::Offset<void> msg) {
    fbb_.AddOffset(ServerEnvelope::VT_MSG, msg);
  }
  explicit ServerEnvelopeBuilder(::flatbuffers::FlatBufferBuilder &_fbb)
        : fbb_(_fbb) {
    start_ = fbb_.StartTable();
  }
  ::flatbuffers::Offset<ServerEnvelope> Finish() {
    const auto end = fbb_.EndTable(start_);
    auto o = ::flatbuffers::Offset<ServerEnvelope>(end);
    return o;
  }
};

inline ::flatbuffers::Offset<ServerEnvelope> CreateServerEnvelope(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    cyberpunk_rp::protocol::ServerMsg msg_type = cyberpunk_rp::protocol::ServerMsg_NONE,
    ::flatbuffers::Offset<void> msg = 0) {
  ServerEnvelopeBuilder builder_(_fbb);
  builder_.add_msg(msg);
  builder_.add_msg_type(msg_type);
  return builder_.Finish();
}

