template <bool B>
inline bool VerifyClientMsgVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyClientMsg(
        verifier,  values->Get(i), types->GetEnum<ClientMsg>(i))) {
      return false;
    }
  }
  return true;
}

